cases.bad:
export function rankToBand(rank: number): TokenFrequencyBand {
  if (rank <= 0 || !Number.isFinite(rank)) return 'none';
  if (rank <= 1000) return 'high';
  if (rank <= 5000) return 'medium';
  if (rank <= 20000) return 'low';
  return 'none';
}

cases.good:
export function rankToBand(rank: number): TokenFrequencyBand {
  if (rank <= 0 || !Number.isFinite(rank)) return 'none';
  if (rank <= 1000) return 'high';
  if (rank <= 5000) return 'medium';
  if (rank <= 20000) return 'low';
  // Any remaining positive rank still has frequency data.
  return 'very-low';
}

cases.bad:
export function entriesToBand(entries: readonly FrequencyEntry[]): TokenFrequencyBand {
  if (entries.length === 0) return 'none';
  const best = Math.min(...entries.map((e) => e.frequency));
  return rankToBand(best);
}

cases.good:
export function entriesToBand(entries: readonly FrequencyEntry[]): TokenFrequencyBand {
  if (entries.length === 0) {
    // Tokenized but no frequency data → color as rarest instead of leaving plain.
    return 'very-low';
  }
  const best = Math.min(...entries.map((e) => e.frequency));
  return rankToBand(best);
}
